import { Component, OnInit } from '@angular/core';
import { FormControl } from '@angular/forms';
import { Router } from '@angular/router';
import { debounceTime, distinctUntilChanged, switchMap, catchError } from 'rxjs/operators';
import { of, EMPTY } from 'rxjs';
import { CompasService } from '../../core/services/compas.service';
import { Compa, Universidad } from '../../shared/models/compa.model';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent implements OnInit {
  activeTab: 'universidades' | 'compas' = 'universidades';

  // Tab universidades
  universidades: Universidad[] = [];
  loadingUnivs = false;
  selectedUniv: string | null = null;
  compasByUniv: Compa[] = [];
  loadingByUniv = false;

  // Tab compas
  searchCtrl = new FormControl('');
  results: Compa[] = [];
  loading = false;
  searched = false;
  error = '';

  constructor(private compasService: CompasService, private router: Router) {}

  ngOnInit(): void {
    this.loadUniversidades();

    this.searchCtrl.valueChanges.pipe(
      debounceTime(400),
      distinctUntilChanged(),
      switchMap((q: any) => {
        if (!q || q.trim().length < 2) {
          this.results  = [];
          this.searched = false;
          this.loading  = false;
          return EMPTY;
        }
        this.loading = true;
        this.error   = '';
        return this.compasService.search(q.trim()).pipe(
          catchError(() => {
            this.error   = 'Error al buscar. Intenta de nuevo.';
            this.loading = false;
            return of([] as Compa[]);
          })
        );
      })
    ).subscribe((data: Compa[]) => {
      this.results  = data;
      this.searched = true;
      this.loading  = false;
    });
  }

  loadUniversidades(): void {
    this.loadingUnivs = true;
    this.compasService.getUniversidades().subscribe({
      next:  u  => { this.universidades = u; this.loadingUnivs = false; },
      error: () => { this.loadingUnivs = false; }
    });
  }

  setTab(tab: 'universidades' | 'compas'): void {
    this.activeTab    = tab;
    this.selectedUniv = null;
    this.searched     = false;
    this.searchCtrl.setValue('', { emitEvent: false });
    this.results      = [];
  }

  selectUniversidad(nombre: string): void {
    this.selectedUniv   = nombre;
    this.loadingByUniv  = true;
    this.compasByUniv   = [];
    this.compasService.getByUniversidad(nombre).subscribe({
      next:  c  => { this.compasByUniv = c; this.loadingByUniv = false; },
      error: () => { this.loadingByUniv = false; }
    });
  }

  backToUnivs(): void {
    this.selectedUniv = null;
    this.compasByUniv = [];
  }

  go(id: number): void {
    this.router.navigate(['/compa', id]);
  }

  initials(u: string): string {
    return u.split(' ').filter(w => w.length > 3).slice(0, 2).map(w => w[0].toUpperCase()).join('') || u[0].toUpperCase();
  }
}
<section class="hero">
  <div class="hero-content">
    <h1>¡Busca y califica a tus compas!</h1>
    <p class="subtitle">Evalúa a tus compañeros de clase o trabajo, o revisa sus calificaciones antes de elegir grupo.</p>

    <!-- Tabs -->
    <div class="tabs-bar">
      <button class="tab-btn" [class.active]="activeTab === 'universidades'" (click)="setTab('universidades')">
        🏛️ UNIVERSIDADES
      </button>
      <button class="tab-btn" [class.active]="activeTab === 'compas'" (click)="setTab('compas')">
        🔍 COMPAÑEROS
      </button>
    </div>

    <!-- Search box (tab compas) -->
    <div class="search-box" *ngIf="activeTab === 'compas'">
      <input
        type="text"
        [formControl]="searchCtrl"
        placeholder="Escribe un nombre o apellido..."
        class="search-input"
        autocomplete="off"
      />
      <span class="search-spinner" *ngIf="loading"></span>
    </div>
  </div>
</section>

<!-- ============  UNIVERSIDADES TAB  ============ -->
<div class="container tab-body" *ngIf="activeTab === 'universidades'">

  <!-- Lista de universidades -->
  <ng-container *ngIf="!selectedUniv">
    <div class="section-header">
      <h2>Universidades registradas</h2>
      <a routerLink="/agregar" class="btn btn-primary btn-sm">+ Agregar compañero</a>
    </div>

    <div class="loading-wrap" *ngIf="loadingUnivs">
      <div class="spinner"></div>
    </div>

    <div class="univ-grid" *ngIf="!loadingUnivs && universidades.length > 0">
      <div class="univ-card" *ngFor="let u of universidades" (click)="selectUniversidad(u.universidad)">
        <div class="univ-initial">{{ initials(u.universidad) }}</div>
        <div class="univ-info">
          <span class="univ-nombre">{{ u.universidad }}</span>
          <span class="univ-count">{{ u.total_compas }} compañero{{ u.total_compas !== 1 ? 's' : '' }}</span>
        </div>
        <span class="arrow">›</span>
      </div>
    </div>

    <div class="empty" *ngIf="!loadingUnivs && universidades.length === 0">
      <div class="empty-icon">🏛️</div>
      <p>Aún no hay universidades registradas.</p>
      <a routerLink="/agregar" class="btn btn-primary" style="margin-top:1rem">Agregar el primer compañero</a>
    </div>
  </ng-container>

  <!-- Compas de la universidad seleccionada -->
  <ng-container *ngIf="selectedUniv">
    <div class="section-header">
      <button class="btn-back" (click)="backToUnivs()">← Volver</button>
      <h2>{{ selectedUniv }}</h2>
    </div>

    <div class="loading-wrap" *ngIf="loadingByUniv">
      <div class="spinner"></div>
    </div>

    <div class="results-grid" *ngIf="!loadingByUniv && compasByUniv.length > 0">
      <div class="compa-card" *ngFor="let c of compasByUniv" (click)="go(c.id)">
        <div class="avatar" [style.background]="'hsl(' + (c.id * 57) + ',55%,55%)'">
          <img *ngIf="c.foto_url" [src]="c.foto_url" [alt]="c.nombre">
          <span *ngIf="!c.foto_url">{{ c.nombre[0] }}{{ c.apellido[0] }}</span>
        </div>
        <div class="card-body">
          <h3>{{ c.nombre }} {{ c.apellido }}</h3>
          <p class="card-meta" *ngIf="c.carrera">{{ c.carrera }}<span *ngIf="c.ciclo"> · {{ c.ciclo }}</span></p>
          <app-star-rating [value]="c.promedio ?? 0" [readonly]="true" size="sm"></app-star-rating>
          <p class="meta">
            <span *ngIf="c.promedio; else sinCalif2">{{ c.promedio | number:'1.1-1' }} / 5</span>
            <ng-template #sinCalif2><span class="no-rating">Sin calificar</span></ng-template>
            &nbsp;·&nbsp; {{ c.total_calificaciones }} reseña{{ c.total_calificaciones !== 1 ? 's' : '' }}
          </p>
        </div>
        <span class="arrow">›</span>
      </div>
    </div>

    <div class="empty" *ngIf="!loadingByUniv && compasByUniv.length === 0">
      <div class="empty-icon">🔎</div>
      <p>No hay compañeros registrados en esta universidad.</p>
    </div>
  </ng-container>
</div>

<!-- ============  COMPAÑEROS TAB  ============ -->
<div class="container tab-body" *ngIf="activeTab === 'compas'">

  <div class="section-header">
    <h2 *ngIf="!searched">Busca a tu compañero</h2>
    <h2 *ngIf="searched">{{ results.length }} resultado{{ results.length !== 1 ? 's' : '' }}</h2>
    <a routerLink="/agregar" class="btn btn-primary btn-sm">+ Agregar compañero</a>
  </div>

  <div class="alert alert-error" *ngIf="error">{{ error }}</div>

  <div class="results-grid" *ngIf="results.length > 0">
    <div class="compa-card" *ngFor="let c of results" (click)="go(c.id)">
      <div class="avatar" [style.background]="'hsl(' + (c.id * 57) + ',55%,55%)'">
        <img *ngIf="c.foto_url" [src]="c.foto_url" [alt]="c.nombre">
        <span *ngIf="!c.foto_url">{{ c.nombre[0] }}{{ c.apellido[0] }}</span>
      </div>
      <div class="card-body">
        <h3>{{ c.nombre }} {{ c.apellido }}</h3>
        <p class="card-meta" *ngIf="c.universidad">{{ c.universidad }}<span *ngIf="c.carrera"> · {{ c.carrera }}</span></p>
        <app-star-rating [value]="c.promedio ?? 0" [readonly]="true" size="sm"></app-star-rating>
        <p class="meta">
          <span *ngIf="c.promedio; else sinCalif">{{ c.promedio | number:'1.1-1' }} / 5</span>
          <ng-template #sinCalif><span class="no-rating">Sin calificar</span></ng-template>
          &nbsp;·&nbsp; {{ c.total_calificaciones }} reseña{{ c.total_calificaciones !== 1 ? 's' : '' }}
        </p>
      </div>
      <span class="arrow">›</span>
    </div>
  </div>

  <div class="empty" *ngIf="searched && results.length === 0 && !error">
    <div class="empty-icon">🔎</div>
    <p>No encontramos compas con ese nombre.</p>
  </div>

  <div class="how-it-works-inline" *ngIf="!searched">
    <div class="steps">
      <div class="step">
        <div class="step-icon-wrap"><span class="step-icon">🔍</span></div>
        <h3>Busca</h3>
        <p>Encuentra a tu compa por nombre o apellido</p>
      </div>
      <div class="step">
        <div class="step-icon-wrap"><span class="step-icon">⭐</span></div>
        <h3>Califica</h3>
        <p>Deja tu puntuación y comentario honesto</p>
      </div>
      <div class="step">
        <div class="step-icon-wrap"><span class="step-icon">🤝</span></div>
        <h3>Conecta</h3>
        <p>Elige mejor a tus compañeros de grupo</p>
      </div>
    </div>
  </div>
</div>
